import React from "react";
import { AbsoluteFill, useCurrentFrame, spring, interpolate } from "remotion";
import { COLORS, FONTS, ENGRAVE_SHADOW, PANEL_SHADOW, STYLE, textForBg } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const label = (n: unknown): string => {
  if (typeof n === "string") return n;
  if (n && typeof n === "object") {
    const v = (n as Record<string, unknown>).label;
    if (typeof v === "string") return v;
    if (typeof v === "number") return String(v);
  }
  return "";
};

const Diagram: React.FC<PrimitiveProps> = ({ anim, fps, dark }) => {
  const frame = useCurrentFrame();
  const p = (anim.params ?? {}) as Record<string, unknown>;

  const title = typeof p.title === "string" ? p.title : typeof anim.text === "string" ? anim.text : "";
  const horizontal = p.layout === "horizontal";
  const nodes = (Array.isArray(p.nodes) ? p.nodes : []).map(label).filter((s) => s.length > 0);

  // Surfaces first, then derive every text colour from the surface it sits on.
  const pageBg = dark ? COLORS.ink : COLORS.papyrus;
  const nodeBg = dark ? COLORS.papyrus : COLORS.vellum;
  const pageText = textForBg(pageBg);
  const nodeText = textForBg(nodeBg);
  const mutedText = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  const radius = STYLE.sharp ? 0 : 14;
  const border = `${Math.max(3, STYLE.panelBorder)}px solid ${COLORS.teal}`;

  const titleIn = spring({ frame, fps, config: { damping: 200, mass: 0.7 }, durationInFrames: Math.round(fps * 0.6) });

  const count = Math.max(nodes.length, 1);
  const size = horizontal ? Math.min(300, 900 / count) : 0;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: pageBg,
        alignItems: "center",
        justifyContent: "center",
        padding: 96,
        fontFamily: FONTS.body,
      }}
    >
      {title ? (
        <div
          style={{
            fontFamily: FONTS.display,
            fontWeight: FONTS.displayWeight,
            fontSize: 84,
            lineHeight: 0.9,
            letterSpacing: "-0.035em",
            textTransform: "uppercase",
            color: pageText,
            textShadow: ENGRAVE_SHADOW,
            marginBottom: 72,
            textAlign: "center",
            opacity: titleIn,
            transform: `translateY(${(1 - titleIn) * -28}px)`,
          }}
        >
          {title}
        </div>
      ) : null}

      <div
        style={{
          display: "flex",
          flexDirection: horizontal ? "row" : "column",
          alignItems: "center",
          justifyContent: "center",
          gap: 0,
          maxWidth: 900,
        }}
      >
        {nodes.map((text, i) => {
          const delay = Math.round(fps * (0.35 + i * 0.22));
          const enter = spring({
            frame: frame - delay,
            fps,
            config: { damping: 200, mass: 0.6 },
            durationInFrames: Math.round(fps * 0.55),
          });
          const arrow = interpolate(
            frame,
            [delay + Math.round(fps * 0.35), delay + Math.round(fps * 0.6)],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <React.Fragment key={`${i}-${text}`}>
              <div
                style={{
                  backgroundColor: nodeBg,
                  color: nodeText,
                  border,
                  borderRadius: radius,
                  boxShadow: PANEL_SHADOW,
                  padding: horizontal ? "36px 24px" : "40px 56px",
                  width: horizontal ? size : 760,
                  minHeight: horizontal ? 200 : undefined,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  textAlign: "center",
                  fontFamily: FONTS.display,
                  fontWeight: FONTS.displayWeight,
                  fontSize: horizontal ? 40 : 52,
                  lineHeight: 1.05,
                  letterSpacing: "-0.02em",
                  textTransform: STYLE.uppercaseTitles ? "uppercase" : "none",
                  opacity: enter,
                  transform: `translate${horizontal ? "X" : "Y"}(${(1 - enter) * 40}px) scale(${0.94 + enter * 0.06})`,
                }}
              >
                {text}
              </div>

              {i < nodes.length - 1 ? (
                <div
                  style={{
                    color: COLORS.gold,
                    fontFamily: FONTS.mono,
                    fontSize: 44,
                    lineHeight: 1,
                    padding: horizontal ? "0 18px" : "18px 0",
                    opacity: arrow,
                  }}
                >
                  {horizontal ? "\u25B6" : "\u25BC"}
                </div>
              ) : null}
            </React.Fragment>
          );
        })}
      </div>

      {nodes.length === 0 ? (
        <div style={{ color: mutedText, fontFamily: FONTS.mono, fontSize: 24, letterSpacing: "0.2em", textTransform: "uppercase" }}>
          {"\u2014"}
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

export default Diagram;
